css:
.gabarito-container {
	font-family: Arial, sans-serif;
	max-width: 600px;
	margin: 0 auto;
	padding: 20px;
}

.gabarito-header {
	text-align: center;
	border-bottom: 2px solid #333;
	padding-bottom: 15px;
	margin-bottom: 20px;
}

.gabarito-header h1 {
	margin: 0;
	font-size: 24px;
}

.gabarito-header h2 {
	margin: 10px 0 0;
	font-size: 18px;
	color: #666;
}

.gabarito-header .identificador {
	font-size: 14px;
	color: #666;
	margin-top: 5px;
}

.gabarito-info {
	display: flex;
	justify-content: space-between;
	margin-bottom: 30px;
	padding: 15px;
	background: #f5f5f5;
	border-radius: 5px;
}

.gabarito-info .info-item {
	text-align: center;
}

.gabarito-info .info-label {
	font-weight: bold;
	font-size: 12px;
	color: #666;
}

.gabarito-info .info-value {
	font-size: 14px;
}

.gabarito-table {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 30px;
}

.gabarito-table th,
.gabarito-table td {
	border: 1px solid #ddd;
	padding: 12px;
	text-align: center;
}

.gabarito-table th {
	background: #333;
	color: white;
}

.gabarito-table tr:nth-child(even) {
	background: #f9f9f9;
}

.gabarito-resposta {
	font-weight: bold;
	font-size: 18px;
}

.gabarito-discursivas {
	margin-top: 30px;
}

.gabarito-discursivas h3 {
	border-bottom: 1px solid #ddd;
	padding-bottom: 10px;
}

.questao-discursiva {
	margin-bottom: 20px;
	padding: 15px;
	background: #f9f9f9;
	border-radius: 5px;
}

.questao-discursiva .questao-numero {
	font-weight: bold;
	margin-bottom: 10px;
}

.questao-discursiva .resposta-label {
	font-weight: bold;
	margin-bottom: 5px;
}

.gabarito-footer {
	text-align: center;
	margin-top: 30px;
	padding-top: 15px;
	border-top: 2px solid #333;
	font-size: 12px;
	color: #666;
}

.aviso-confidencial {
	background: #fff3cd;
	border: 1px solid #ffc107;
	padding: 10px;
	margin-bottom: 20px;
	border-radius: 5px;
	text-align: center;
	font-weight: bold;
}
